format_code:
hardware {
    pin led: Output = 2
}

task blink {
    every 500ms { led.toggle() }
}

machine DevState {
    initial state idle {
        on activate() -> running
    }

    state running {
        on deactivate() -> idle
    }
}

setup {
    run(blink)
}

system_graph.mermaid:
flowchart LR
    u_setup["setup"]
    s_run{{"run"}}
    u_DevState[["DevState"]]
    s_activate{{"activate"}}
    s_deactivate{{"deactivate"}}
    u_blink(("blink<br>↻ 500ms"))
    u_setup -->|run| s_run
